const chess = new Chess()
chess.put({ type: 'p', color: 'w' }, 'h8')
console.log('w h8:', chess.moves({ square: 'h8', verbose: true }))

// black pawn on rank-1 corners and edges
for (const sq of ['a1', 'h1', 'a8', 'h8'] as const) {
  const c = new Chess()
  const color = sq.endsWith('1') ? 'b' : 'w'
  try {
    c.put({ type: 'p', color }, sq)
