    chess.move('f7')
    const result = chess.pgn()
    expect(result.match(/(45\. f7 \*)$/)?.[0]).toBe('45. f7 *')
  })

  it('Github Issue #98 (black) - Wrong movement number after setting a position via FEN', () => {
    const chess = new Chess()
