    const chess = new Chess()
    chess.clear()
    expect(() => chess.move('e4')).toThrowError()
  })

  it('Github Issue #279 - loadPgn duplicates last move if it has a comment', () => {
    const history = [
      'e4',
      'e5',
      'Nf3',
      'Nc6',
      'Bb5',
      'd6',
      'd4',
      'Bd7',
      'Nc3',
      'Nf6',
      'Bxc6',
    ]

    // trailing comment - no end of game marker
    const chess = new Chess()
    chess.loadPgn(
      '1. e4 e5 2. Nf3 Nc6 3. Bb5 d6 ' +
        '4. d4 Bd7 5. Nc3 Nf6 6. Bxc6 {comment}',
    )
    expect(chess.history()).toEqual(history)
    expect(chess.header()['Result']).toBe('*')

    // trailing comment - end of game marker after comment
    chess.loadPgn(
      '1. e4 e5 2. Nf3 Nc6 3. Bb5 d6 ' +
        '4. d4 Bd7 5. Nc3 Nf6 6. Bxc6 {comment} *',
    )
    expect(chess.history()).toEqual(history)
    expect(chess.getHeaders()['Result']).toBe('*')

    // trailing comment - end of game marker before comment
    chess.loadPgn(
      '1. e4 e5 2. Nf3 Nc6 3. Bb5 d6 ' +
        '4. d4 Bd7 5. Nc3 Nf6 6. Bxc6 * {comment}',
    )
    expect(chess.history()).toEqual(history)
    expect(chess.getHeaders()['Result']).toBe('*')

    // trailing comment with PGN header - no end of game marker
    chess.loadPgn(
      '[White "name"]\n\n' +
        '1. e4 e5 2. Nf3 Nc6 ' +
        '3. Bb5 d6 ' +
        '4. d4 Bd7 5. Nc3 Nf6 ' +
        '6. Bxc6 {comment}',
    )
    expect(chess.history()).toEqual(history)
    expect(chess.getHeaders()['Result']).toBe('*')

    // trailing comment with result header - end of game marker after comment
    chess.loadPgn(
      '[White "name"]\n\n' +
        '1. e4 e5 2. Nf3 Nc6 3. Bb5 d6 ' +
        '4. d4 Bd7 5. Nc3 Nf6 6. Bxc6 {comment} *',
    )
    expect(chess.history()).toEqual(history)
    expect(chess.header()['Result']).toBe('*')

    // trailing comment with result header - end of game marker before comment
    chess.loadPgn(
      '[White "name"]\n\n' +
        '1. e4 e5 2. Nf3 Nc6 3. Bb5 d6 ' +
        '4. d4 Bd7 5. Nc3 Nf6 6. Bxc6 1/2-1/2 {comment}',
    )
    expect(chess.history()).toEqual(history)
    expect(chess.header()['Result']).toBe('1/2-1/2')
  })

  it('Github Issue #286 - pgn should not generate sloppy moves', () => {
    const chess = new Chess()
    chess.loadPgn('1. e4 d5 2. Nf3 Nd7 3. Bb5 Nf6 4. O-O')
    expect(chess.pgn()).toBe(`${SEVEN_TAG_ROSTER_STRING}
1. e4 d5 2. Nf3 Nd7 3. Bb5 Nf6 4. O-O *`)
  })

  it('Github Issue #321 - strict parser should always run before permissive', () => {
    const chess = new Chess()
    // these test examples are lifted from the github issue
    chess.load('r4rk1/4nqpp/1p1p4/2pPpp2/bPP1P3/R1B1NQ2/P4PPP/1R4K1 w - - 0 28')
    chess.move('bxc5')
    chess.undo()
    chess.move('bxc5', { strict: true })

    // over-disambiguation with strict should fail
    chess.load(
      'rnbqk2r/p1pp1ppp/1p2pn2/8/1bPP4/2N1P3/PP3PPP/R1BQKBNR w KQkq - 0 5',
    )
    expect(() => chess.move('Nge2', { strict: true })).toThrowError()
    // permisssive should work
    chess.move('Nge2')
  })

  it('Github Issue #326a - ignore whitespace after header tag (loadPgn)', () => {
    let chess = new Chess()
    const pgn = `
    [white "player a"]
         [black "player b"]
              [note "whitespace after right bracket"]

            1. e4 e5`

    chess.loadPgn(pgn)
  })

  it('Github Issue #326b - ignore whitespace in line after header (loadPgn)', () => {
    const chess = new Chess()
    const pgn = `
    [white "player a"]
         [black "player b"]
              [note "whitespace after right bracket and in empty line below"]

            1. e4 e5`

    chess.loadPgn(pgn)
  })

  it('Github Issue #113 - cannot parse pgn not starting with move number 1', () => {
    const chess = new Chess()
    const pgn = `[Event "SampleSite"]
    [Site "?"]
    [Date "2008-01-04"]
    [Round "2"]
    [White "Zhou Jianchao"]
    [Black "Fidaeyee, H."]
    [Result "1-0"]
    [BlackElo "2074"]
    [FEN "1n1r3r/1k2q1p1/1bp1p2p/5p2/2Pp1B2/5QN1/5PPP/RR4K1 w - - 0 29"]
    [PlyCount "1"]
    [SetUp "1"]
    [SourceDate "2012.04.30"]
    [WhiteElo "2551"]

    29. Rxb6+ Kxb6 30. Qb3+ Qb4 31. Qxb4# 1-0`

    chess.loadPgn(pgn)

    expect(chess.moveNumber()).toBe(31)
  })

  it('Github Issue #552 - ignore invalid castling rights', () => {
    const chess = new Chess('kb4r1/p2n3P/1PP5/1P6/8/8/6p1/R3KR2 b KQkq - 0 19')
    expect(chess.isGameOver()).toBe(false) // this was crashing due to invalid castling moves being generated
  })

  it('BigInt error when generating moves for pawns on edge ranks', () => {
    const chess = new Chess()
    chess.put({ type: 'p', color: 'w' }, 'h8')
    expect(() => chess.moves({ square: 'h8', verbose: true })).not.toThrow()
    expect(chess.moves({ square: 'h8', verbose: true })).toEqual([])
    expect(chess.moves({ square: 'h8' })).toEqual([])

    // black pawn on rank 1 would otherwise generate phantom promotion moves
    const chess2 = new Chess()
    chess2.put({ type: 'p', color: 'b' }, 'a1')
    expect(() => chess2.moves({ square: 'a1', verbose: true })).not.toThrow()
    expect(chess2.moves({ square: 'a1', verbose: true })).toEqual([])
    expect(chess2.moves({ square: 'a1' })).toEqual([])
  })
})

